CREATE TABLE public.customer_credit_accounts (user_id uuid PRIMARY KEY, balance_cents bigint NOT NULL DEFAULT 0 CHECK(balance_cents>=0), reserved_cents bigint NOT NULL DEFAULT 0 CHECK(reserved_cents>=0 AND reserved_cents<=balance_cents), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.customer_credit_accounts TO authenticated; GRANT ALL ON public.customer_credit_accounts TO service_role;
ALTER TABLE public.customer_credit_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY credit_account_read ON public.customer_credit_accounts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.customer_credit_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.customer_credit_accounts(user_id), amount_cents bigint NOT NULL CHECK(amount_cents<>0), balance_after_cents bigint NOT NULL CHECK(balance_after_cents>=0), description text NOT NULL, order_id uuid REFERENCES public.orders(id), refund_id uuid, actor_id uuid, operation_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.customer_credit_entries TO authenticated; GRANT ALL ON public.customer_credit_entries TO service_role;
ALTER TABLE public.customer_credit_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY credit_entry_read ON public.customer_credit_entries FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX credit_entries_user_date ON public.customer_credit_entries(user_id,created_at DESC);
CREATE TABLE public.customer_payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), user_id uuid NOT NULL, total_cents bigint NOT NULL CHECK(total_cents>=0), credit_cents bigint NOT NULL CHECK(credit_cents>=0), provider_cents bigint NOT NULL CHECK(provider_cents>=0 AND credit_cents+provider_cents=total_cents), provider text NOT NULL CHECK(provider IN ('mercadopago','stripe','credit')), provider_id text UNIQUE, status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','pending','approved','released','review')), created_at timestamptz NOT NULL DEFAULT now(), settled_at timestamptz, operation_key text NOT NULL UNIQUE);
GRANT SELECT ON public.customer_payment_attempts TO authenticated; GRANT ALL ON public.customer_payment_attempts TO service_role;
ALTER TABLE public.customer_payment_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY credit_attempt_read ON public.customer_payment_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_open_credit_attempt ON public.customer_payment_attempts(order_id) WHERE status IN ('reserved','pending','approved','review');
CREATE TABLE public.customer_refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, order_id uuid NOT NULL REFERENCES public.orders(id), item_id uuid REFERENCES public.order_items(id), amount_cents bigint NOT NULL CHECK(amount_cents>0), reason text NOT NULL, choice text CHECK(choice IN ('credit','original')), status text NOT NULL DEFAULT 'awaiting_choice' CHECK(status IN ('awaiting_choice','credited','awaiting_approval','approved','processing','refunded','declined','revoked','failed','review')), token_hash text NOT NULL, token_expires_at timestamptz NOT NULL, token_version integer NOT NULL DEFAULT 1, chosen_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, approved_by uuid, decision_reason text, provider_id text, provider_refund_id text, provider_cents bigint NOT NULL DEFAULT 0, credit_cents bigint NOT NULL DEFAULT 0, external_confirmed_cents bigint NOT NULL DEFAULT 0, email_status text, operation_key text NOT NULL UNIQUE);
GRANT SELECT ON public.customer_refunds TO authenticated; GRANT ALL ON public.customer_refunds TO service_role;
ALTER TABLE public.customer_refunds ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_refund_read ON public.customer_refunds FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.customer_finance_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), refund_id uuid REFERENCES public.customer_refunds(id), order_id uuid REFERENCES public.orders(id), user_id uuid NOT NULL, actor_id uuid, action text NOT NULL, amount_cents bigint, reason text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.customer_finance_audit TO authenticated; GRANT ALL ON public.customer_finance_audit TO service_role;
ALTER TABLE public.customer_finance_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_audit_admin ON public.customer_finance_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.orders ADD COLUMN store_credit_cents bigint NOT NULL DEFAULT 0, ADD COLUMN finance_settled_at timestamptz;
CREATE FUNCTION public.finance_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Financial history is append only'; END $$;
CREATE TRIGGER credit_entries_immutable BEFORE UPDATE OR DELETE ON public.customer_credit_entries FOR EACH ROW EXECUTE FUNCTION public.finance_immutable();
CREATE TRIGGER finance_audit_immutable BEFORE UPDATE OR DELETE ON public.customer_finance_audit FOR EACH ROW EXECUTE FUNCTION public.finance_immutable();
CREATE FUNCTION public.finance_assert_admin(p_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=p_actor AND r.role='admin' AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<now())) THEN RAISE EXCEPTION 'Active administrator required'; END IF; END $$;
REVOKE ALL ON FUNCTION public.finance_assert_admin(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_assert_admin(uuid) TO service_role;
CREATE FUNCTION public.finance_adjust_credit(p_user uuid,p_actor uuid,p_amount bigint,p_reason text,p_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.customer_credit_accounts; e public.customer_credit_entries; BEGIN PERFORM public.finance_assert_admin(p_actor); IF p_amount=0 OR abs(p_amount)>100000000 OR length(trim(p_reason))<5 OR length(p_key)<8 THEN RAISE EXCEPTION 'Invalid adjustment'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user) THEN RAISE EXCEPTION 'Customer not found'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_key,0)); SELECT * INTO e FROM public.customer_credit_entries WHERE operation_key=p_key; IF FOUND THEN IF e.user_id<>p_user OR e.amount_cents<>p_amount OR e.actor_id<>p_actor OR e.description<>p_reason THEN RAISE EXCEPTION 'Idempotency conflict'; END IF; RETURN to_jsonb(e); END IF; INSERT INTO public.customer_credit_accounts(user_id) VALUES(p_user) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.customer_credit_accounts WHERE user_id=p_user FOR UPDATE; IF a.balance_cents+p_amount<a.reserved_cents THEN RAISE EXCEPTION 'Insufficient available credit'; END IF; UPDATE public.customer_credit_accounts SET balance_cents=balance_cents+p_amount,updated_at=now() WHERE user_id=p_user RETURNING * INTO a; INSERT INTO public.customer_credit_entries(user_id,amount_cents,balance_after_cents,description,actor_id,operation_key) VALUES(p_user,p_amount,a.balance_cents,p_reason,p_actor,p_key) RETURNING * INTO e; INSERT INTO public.customer_finance_audit(user_id,actor_id,action,amount_cents,reason) VALUES(p_user,p_actor,'credit_adjustment',p_amount,p_reason); RETURN to_jsonb(e); END $$;
REVOKE ALL ON FUNCTION public.finance_adjust_credit(uuid,uuid,bigint,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_adjust_credit(uuid,uuid,bigint,text,text) TO service_role;
CREATE FUNCTION public.finance_reserve_payment(p_order uuid,p_user uuid,p_credit bigint,p_provider text,p_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; a public.customer_credit_accounts; t public.customer_payment_attempts; BEGIN IF p_credit<0 OR length(p_key)<8 THEN RAISE EXCEPTION 'Invalid payment'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE; IF NOT FOUND OR o.user_id<>p_user OR o.status<>'pending' THEN RAISE EXCEPTION 'Order not payable'; END IF; SELECT * INTO t FROM public.customer_payment_attempts WHERE operation_key=p_key; IF FOUND THEN IF t.order_id<>p_order OR t.user_id<>p_user OR t.credit_cents<>p_credit THEN RAISE EXCEPTION 'Idempotency conflict'; END IF; RETURN to_jsonb(t); END IF; IF EXISTS(SELECT 1 FROM public.customer_payment_attempts WHERE order_id=p_order AND status IN ('reserved','pending','approved','review')) THEN RAISE EXCEPTION 'Previous payment must be reconciled'; END IF; IF p_credit>o.total_cents THEN RAISE EXCEPTION 'Credit exceeds total'; END IF; INSERT INTO public.customer_credit_accounts(user_id) VALUES(p_user) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.customer_credit_accounts WHERE user_id=p_user FOR UPDATE; IF p_credit>a.balance_cents-a.reserved_cents THEN RAISE EXCEPTION 'Insufficient available credit'; END IF; UPDATE public.customer_credit_accounts SET reserved_cents=reserved_cents+p_credit,updated_at=now() WHERE user_id=p_user; INSERT INTO public.customer_payment_attempts(order_id,user_id,total_cents,credit_cents,provider_cents,provider,operation_key) VALUES(p_order,p_user,o.total_cents,p_credit,o.total_cents-p_credit,CASE WHEN p_credit=o.total_cents THEN 'credit' ELSE p_provider END,p_key) RETURNING * INTO t; UPDATE public.orders SET store_credit_cents=p_credit WHERE id=p_order; RETURN to_jsonb(t); END $$;
REVOKE ALL ON FUNCTION public.finance_reserve_payment(uuid,uuid,bigint,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_reserve_payment(uuid,uuid,bigint,text,text) TO service_role;
CREATE FUNCTION public.finance_settle_payment(p_attempt uuid,p_provider_id text,p_amount bigint,p_currency text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.customer_payment_attempts; a public.customer_credit_accounts; o public.orders; BEGIN SELECT * INTO t FROM public.customer_payment_attempts WHERE id=p_attempt; IF NOT FOUND THEN RAISE EXCEPTION 'Attempt missing'; END IF; SELECT * INTO o FROM public.orders WHERE id=t.order_id FOR UPDATE; SELECT * INTO t FROM public.customer_payment_attempts WHERE id=p_attempt FOR UPDATE; IF t.status='approved' THEN RETURN false; END IF; IF t.status NOT IN ('reserved','pending') OR o.status<>'pending' OR p_currency<>'BRL' OR p_amount<>t.provider_cents OR (t.provider<>'credit' AND (t.provider_id IS NULL OR t.provider_id IS DISTINCT FROM p_provider_id)) THEN RAISE EXCEPTION 'Payment requires reconciliation'; END IF; SELECT * INTO a FROM public.customer_credit_accounts WHERE user_id=t.user_id FOR UPDATE; IF a.reserved_cents<t.credit_cents THEN RAISE EXCEPTION 'Credit hold missing'; END IF; UPDATE public.customer_credit_accounts SET balance_cents=balance_cents-t.credit_cents,reserved_cents=reserved_cents-t.credit_cents,updated_at=now() WHERE user_id=t.user_id RETURNING * INTO a; IF t.credit_cents>0 THEN INSERT INTO public.customer_credit_entries(user_id,amount_cents,balance_after_cents,description,order_id,operation_key) VALUES(t.user_id,-t.credit_cents,a.balance_cents,'Pagamento com saldo Sevii',t.order_id,'payment:'||t.id); END IF; UPDATE public.customer_payment_attempts SET status='approved',settled_at=now() WHERE id=t.id; UPDATE public.orders SET finance_settled_at=now() WHERE id=t.order_id; INSERT INTO public.customer_finance_audit(user_id,order_id,action,amount_cents) VALUES(t.user_id,t.order_id,'payment_settled',t.total_cents); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.finance_settle_payment(uuid,text,bigint,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_settle_payment(uuid,text,bigint,text) TO service_role;
CREATE FUNCTION public.finance_release_payment(p_attempt uuid,p_provider_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.customer_payment_attempts; BEGIN SELECT * INTO t FROM public.customer_payment_attempts WHERE id=p_attempt; IF NOT FOUND THEN RETURN; END IF; PERFORM 1 FROM public.orders WHERE id=t.order_id FOR UPDATE; SELECT * INTO t FROM public.customer_payment_attempts WHERE id=p_attempt FOR UPDATE; IF t.status='released' THEN RETURN; END IF; IF t.status NOT IN ('reserved','pending') OR t.provider_id IS DISTINCT FROM p_provider_id THEN RAISE EXCEPTION 'Cannot release this payment'; END IF; UPDATE public.customer_credit_accounts SET reserved_cents=reserved_cents-t.credit_cents,updated_at=now() WHERE user_id=t.user_id; UPDATE public.customer_payment_attempts SET status='released' WHERE id=t.id; UPDATE public.orders SET store_credit_cents=0 WHERE id=t.order_id AND finance_settled_at IS NULL; INSERT INTO public.customer_finance_audit(user_id,order_id,action,amount_cents) VALUES(t.user_id,t.order_id,'payment_released',t.credit_cents); END $$;
REVOKE ALL ON FUNCTION public.finance_release_payment(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_release_payment(uuid,text) TO service_role;
CREATE FUNCTION public.finance_create_refund(p_order uuid,p_item uuid,p_actor uuid,p_amount bigint,p_reason text,p_hash text,p_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; r public.customer_refunds; committed bigint; ceiling bigint; BEGIN PERFORM public.finance_assert_admin(p_actor); IF p_amount<=0 OR length(trim(p_reason))<5 OR p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid refund'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE; IF NOT FOUND OR o.user_id IS NULL OR NOT (o.status IN ('paid','preparing','separated','shipped','awaiting_pickup','cards_pending_delivery','delivered') OR o.payment_paid_at IS NOT NULL OR o.finance_settled_at IS NOT NULL) THEN RAISE EXCEPTION 'Order has no confirmed payment'; END IF; SELECT * INTO r FROM public.customer_refunds WHERE operation_key=p_key; IF FOUND THEN IF r.order_id<>p_order OR r.amount_cents<>p_amount OR r.item_id IS DISTINCT FROM p_item OR r.created_by<>p_actor OR r.reason<>p_reason THEN RAISE EXCEPTION 'Idempotency conflict'; END IF; RETURN to_jsonb(r)-'token_hash'; END IF; SELECT coalesce(sum(amount_cents-external_confirmed_cents),0) INTO committed FROM public.customer_refunds WHERE order_id=p_order AND status NOT IN ('declined','revoked','refunded','credited'); ceiling:=o.total_cents-coalesce(o.refunded_cents,0)-committed; IF p_amount>ceiling THEN RAISE EXCEPTION 'Refund exceeds remaining paid amount'; END IF; IF p_item IS NOT NULL THEN SELECT floor(unit_price_cents::numeric*quantity*greatest(0,1-coalesce(o.discount_cents,0)::numeric/nullif(o.subtotal_cents,0))) INTO ceiling FROM public.order_items WHERE id=p_item AND order_id=p_order; IF ceiling IS NULL THEN RAISE EXCEPTION 'Item not in order'; END IF; SELECT coalesce(sum(amount_cents),0) INTO committed FROM public.customer_refunds WHERE item_id=p_item AND status NOT IN ('declined','revoked'); IF p_amount>ceiling-committed-coalesce((SELECT refund_cents FROM public.order_items WHERE id=p_item),0) THEN RAISE EXCEPTION 'Refund exceeds item allocation'; END IF; END IF; INSERT INTO public.customer_refunds(user_id,order_id,item_id,amount_cents,reason,token_hash,token_expires_at,created_by,operation_key,provider_id) VALUES(o.user_id,o.id,p_item,p_amount,p_reason,p_hash,now()+interval '7 days',p_actor,p_key,o.mercadopago_payment_id) RETURNING * INTO r; INSERT INTO public.customer_finance_audit(refund_id,order_id,user_id,actor_id,action,amount_cents,reason) VALUES(r.id,o.id,o.user_id,p_actor,'refund_created',p_amount,p_reason); RETURN to_jsonb(r)-'token_hash'; END $$;
REVOKE ALL ON FUNCTION public.finance_create_refund(uuid,uuid,uuid,bigint,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_create_refund(uuid,uuid,uuid,bigint,text,text,text) TO service_role;
CREATE FUNCTION public.finance_choose_refund(p_id uuid,p_hash text,p_choice text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.customer_refunds; a public.customer_credit_accounts; BEGIN SELECT * INTO r FROM public.customer_refunds WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Link unavailable'; END IF; PERFORM 1 FROM public.orders WHERE id=r.order_id FOR UPDATE; SELECT * INTO r FROM public.customer_refunds WHERE id=p_id FOR UPDATE; IF r.token_hash<>p_hash OR r.token_expires_at<=now() OR r.status<>'awaiting_choice' OR p_choice NOT IN ('credit','original') THEN RAISE EXCEPTION 'Link unavailable'; END IF; IF p_choice='credit' THEN INSERT INTO public.customer_credit_accounts(user_id) VALUES(r.user_id) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.customer_credit_accounts WHERE user_id=r.user_id FOR UPDATE; UPDATE public.customer_credit_accounts SET balance_cents=balance_cents+r.amount_cents,updated_at=now() WHERE user_id=r.user_id RETURNING * INTO a; INSERT INTO public.customer_credit_entries(user_id,amount_cents,balance_after_cents,description,order_id,refund_id,operation_key) VALUES(r.user_id,r.amount_cents,a.balance_cents,'Reembolso: '||r.reason,r.order_id,r.id,'refund:'||r.id); UPDATE public.orders SET refunded_cents=coalesce(refunded_cents,0)+r.amount_cents WHERE id=r.order_id; END IF; UPDATE public.customer_refunds SET choice=p_choice,chosen_at=now(),status=CASE WHEN p_choice='credit' THEN 'credited' ELSE 'awaiting_approval' END,completed_at=CASE WHEN p_choice='credit' THEN now() ELSE NULL END WHERE id=r.id RETURNING * INTO r; INSERT INTO public.customer_finance_audit(refund_id,order_id,user_id,action,amount_cents) VALUES(r.id,r.order_id,r.user_id,'choice_'||p_choice,r.amount_cents); RETURN to_jsonb(r)-'token_hash'; END $$;
REVOKE ALL ON FUNCTION public.finance_choose_refund(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_choose_refund(uuid,text,text) TO service_role;
CREATE FUNCTION public.finance_refund_action(p_id uuid,p_actor uuid,p_action text,p_reason text,p_hash text DEFAULT NULL,p_external bigint DEFAULT NULL,p_reference text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.customer_refunds; o public.orders; t public.customer_payment_attempts; a public.customer_credit_accounts; prior_credit bigint; prior_external bigint; credit_remaining bigint; external_remaining bigint; BEGIN PERFORM public.finance_assert_admin(p_actor); IF length(trim(p_reason))<5 THEN RAISE EXCEPTION 'Reason required'; END IF; SELECT * INTO r FROM public.customer_refunds WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Refund missing'; END IF; SELECT * INTO o FROM public.orders WHERE id=r.order_id FOR UPDATE; SELECT * INTO r FROM public.customer_refunds WHERE id=p_id FOR UPDATE;
IF p_action='renew' THEN IF r.status<>'awaiting_choice' OR p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Cannot renew'; END IF; UPDATE public.customer_refunds SET token_hash=p_hash,token_expires_at=now()+interval '7 days',token_version=token_version+1 WHERE id=r.id;
ELSIF p_action='revoke' THEN IF r.status<>'awaiting_choice' THEN RAISE EXCEPTION 'Cannot revoke'; END IF; UPDATE public.customer_refunds SET status='revoked' WHERE id=r.id;
ELSIF p_action='decline' THEN IF r.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Cannot decline'; END IF; UPDATE public.customer_refunds SET status='declined',decision_reason=p_reason,approved_by=p_actor WHERE id=r.id;
ELSIF p_action='approve' THEN IF r.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Cannot approve'; END IF; UPDATE public.customer_refunds SET status='approved',approved_by=p_actor,decision_reason=p_reason WHERE id=r.id;
ELSIF p_action='process' THEN IF r.status IN ('processing','review','failed') THEN RETURN to_jsonb(r)-'token_hash'; END IF; IF r.status<>'approved' THEN RAISE EXCEPTION 'Approval required'; END IF; SELECT * INTO t FROM public.customer_payment_attempts WHERE order_id=r.order_id AND status='approved'; IF FOUND THEN SELECT coalesce(sum(credit_cents),0),coalesce(sum(provider_cents),0) INTO prior_credit,prior_external FROM public.customer_refunds WHERE order_id=r.order_id AND id<>r.id AND status IN ('processing','review','failed','refunded'); credit_remaining:=greatest(0,t.credit_cents-prior_credit); external_remaining:=greatest(0,t.provider_cents-prior_external); r.credit_cents:=least(credit_remaining,round(r.amount_cents::numeric*t.credit_cents/nullif(t.total_cents,0))::bigint); r.provider_cents:=r.amount_cents-r.credit_cents; IF r.provider_cents>external_remaining THEN r.credit_cents:=r.credit_cents+r.provider_cents-external_remaining; r.provider_cents:=external_remaining; END IF; IF r.credit_cents>credit_remaining THEN RAISE EXCEPTION 'Original allocation exhausted'; END IF;
ELSE IF coalesce(o.wallet_deduction_cents,0)>0 OR o.coupon_code IS NOT NULL THEN RAISE EXCEPTION 'Historical tender needs manual reconciliation'; END IF; r.credit_cents:=0; r.provider_cents:=r.amount_cents; END IF; UPDATE public.customer_refunds SET status='processing',credit_cents=r.credit_cents,provider_cents=r.provider_cents WHERE id=r.id;
ELSIF p_action='complete' THEN IF r.status='refunded' THEN RETURN to_jsonb(r)-'token_hash'; END IF; IF r.status NOT IN ('processing','review','failed') OR p_external IS DISTINCT FROM r.provider_cents OR (r.provider_cents>0 AND length(coalesce(p_reference,''))<3) THEN RAISE EXCEPTION 'Confirmed refund required'; END IF; IF r.credit_cents>0 THEN INSERT INTO public.customer_credit_accounts(user_id) VALUES(r.user_id) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.customer_credit_accounts WHERE user_id=r.user_id FOR UPDATE; UPDATE public.customer_credit_accounts SET balance_cents=balance_cents+r.credit_cents,updated_at=now() WHERE user_id=r.user_id RETURNING * INTO a; INSERT INTO public.customer_credit_entries(user_id,amount_cents,balance_after_cents,description,order_id,refund_id,actor_id,operation_key) VALUES(r.user_id,r.credit_cents,a.balance_cents,'Devolução da parcela paga com saldo',r.order_id,r.id,p_actor,'refund-original:'||r.id); END IF; UPDATE public.orders SET refunded_cents=coalesce(refunded_cents,0)+r.amount_cents WHERE id=r.order_id; UPDATE public.customer_refunds SET status='refunded',completed_at=now(),external_confirmed_cents=r.provider_cents,provider_refund_id=p_reference WHERE id=r.id;
ELSIF p_action IN ('failed','review') THEN IF r.status NOT IN ('processing','review','failed') THEN RAISE EXCEPTION 'Invalid processing state'; END IF; UPDATE public.customer_refunds SET status=p_action,decision_reason=p_reason WHERE id=r.id;
ELSE RAISE EXCEPTION 'Unknown action'; END IF;
INSERT INTO public.customer_finance_audit(refund_id,order_id,user_id,actor_id,action,amount_cents,reason) VALUES(r.id,r.order_id,r.user_id,p_actor,p_action,r.amount_cents,p_reason); SELECT * INTO r FROM public.customer_refunds WHERE id=p_id; RETURN to_jsonb(r)-'token_hash'; END $$;
REVOKE ALL ON FUNCTION public.finance_refund_action(uuid,uuid,text,text,text,bigint,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finance_refund_action(uuid,uuid,text,text,text,bigint,text) TO service_role;